package main

import "fmt"

func total(price, quantity int) (int, error) {
    if price < 0 || quantity < 0 { return 0, fmt.Errorf("negative value") }
    return price * quantity, nil
}
func main() {
    value, err := total(12, 3)
    if err != nil { panic(err) }
    fmt.Println(value)
    zero, _ := total(12, 0)
    fmt.Println(zero)
    if _, err := total(12, -1); err != nil { fmt.Println("Invalid input rejected") }
}
